// Independent JOSE verification of tokens generated by Rust, including raw P-521 signatures.
const fs=require('node:fs'),path=require('node:path');
(async()=>{const modules=process.env.MOLEAPI_POSTMAN_NODE_MODULES||'/tmp/moleapi-postman-runtime-qa/node_modules';const jose=require(path.join(modules,'jose'));const keys=JSON.parse(fs.readFileSync(path.join(__dirname,'../crates/core/tests/fixtures/asap/keys.json'),'utf8'));const tokens=JSON.parse(fs.readFileSync(process.argv[2]||'/tmp/moleapi-asap-tokens.json','utf8'));
 for(const item of tokens){const family=item.algorithm.startsWith('ES')?item.algorithm:'RSA';const key=await jose.importSPKI(keys[family].public,item.algorithm);const result=await jose.jwtVerify(item.token,key,{algorithms:[item.algorithm],issuer:'fixture-issuer',audience:'fixture-api',currentDate:new Date(1700000000000)});if(result.protectedHeader.kid!==`fixture-${item.algorithm}`||result.payload.sub!=='fixture-issuer'||result.payload.jti!=='fixture-id'||result.payload.custom!=='claim')throw Error('ASAP claims/header differ');}
 console.log(`${tokens.length} Rust ASAP tokens independently verified by Node JOSE`);
})().catch(error=>{console.error(error);process.exit(1)});
